CREATE FUNCTION public.pm_b1_financial_resources(_project uuid, _preview boolean DEFAULT false) RETURNS SETOF jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE r record; projected jsonb; BEGIN IF auth.uid() IS NULL OR NOT public.is_psa_staff() OR _project IS NULL THEN RETURN; END IF; IF NOT EXISTS(SELECT 1 FROM public.pm_projects p WHERE p.id=_project AND NOT p.finance_only AND (public.has_role(auth.uid(),'admin') OR public.pm_can_view_projects(auth.uid()) OR public.pm_has_assigned_access(auth.uid(),p.id))) THEN RETURN; END IF; IF NOT (_preview OR public.pm_project_b1_active()) THEN RETURN; END IF; FOR r IN SELECT id,name,full_name,role,billing_role,proposal_role,color,active,team,collaborator_id,weekly_capacity,hourly_rate_is_override,created_at,updated_at,hourly_rate,sale_rate,cost_rate FROM public.pm_resources ORDER BY name,id LOOP projected:=public.pm_b1_redact_proposed(to_jsonb(r),_project,'resource'); RETURN NEXT projected; END LOOP; END $$;
REVOKE ALL ON FUNCTION public.pm_b1_financial_resources(uuid,boolean) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.pm_b1_financial_resources(uuid,boolean) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.pm_b1_resources(_project uuid DEFAULT NULL) RETURNS SETOF jsonb LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path=public AS $$ BEGIN IF public.pm_project_b1_active() AND _project IS NOT NULL THEN RETURN QUERY SELECT * FROM public.pm_b1_financial_resources(_project,false); ELSE RETURN QUERY SELECT public.pm_b1_resource(r.id,_project) FROM public.pm_resources_public r ORDER BY r.name; END IF; END $$;
COMMENT ON FUNCTION public.pm_b1_financial_resources(uuid,boolean) IS 'Caller-scoped B1 sale/cost resource projection; enumerates after PSA/project authorization instead of the legacy security-invoker rate view. Preview applies the same proposed areas without changing the gate, and exposes no salary inputs.';